        "버튼에는 밭, 담, 길 중 무엇이 되는지가 적혀 있지 않습니다.",
        "결과는 그 입력을 한 다음 계절이 꽤 지난 뒤에 나타납니다. 바로 보고 다음 칸을 고를 시간은 짧습니다.",
