      ko: "셰프의 물리학은 열, 수분, 속도의 칸으로 식감을 맞추는 오늘의 서비스입니다. 기다리기는 열을 올리고 수분을 빼고, 식히기는 반대로 움직입니다. 자르기는 한 번이며 속도만 느려집니다. 정답 순서를 미리 적어 두지 않습니다.",
      en: "Chef Physics is a daily service that hits a texture from bins of heat, moisture, and speed. Wait raises heat and drops moisture. Cool does the opposite. Cut is once, and it only slows the toss. The order is not written down ahead of time.",
