      en: "Three cells are heat and three are moisture. Fast means the piece is still whole. Slow means it was cut once. Crisp is fast, heat 2, moisture 0. Moist is slow, heat 1, moisture 1. Dry is slow, heat 2, moisture 0. Toss keeps the plate only when the bins match the target.",
