      zh: "三格是热，三格是水分。快表示还没切开，慢表示已经切开一次。酥是快、热2、水分0。润是慢、热1、水分1。干是慢、热2、水分0。只有现在的格子和目标一致时，扔进才会过这一盘。",
      fr: "Trois cases sont la chaleur, trois sont l'eau. Vite veut dire que la pièce est encore entière. Lent veut dire qu'elle a été coupée une fois. Croustillant est vite, chaleur 2, eau 0. Moelleux est lent, chaleur 1, eau 1. Sec est lent, chaleur 2, eau 0. Lancer ne garde l'assiette que si les cases visent juste.",
      es: "Tres casillas son el calor y tres el agua. Rápido significa que la pieza sigue entera. Lento significa que ya se cortó una vez. Crujiente es rápido, calor 2, agua 0. Jugoso es lento, calor 1, agua 1. Seco es lento, calor 2, agua 0. Lanzar conserva el plato solo cuando las casillas coinciden con la meta.",
