        "最初の公開は手札から出た牌の役割点だけを足して30点以上必要で、場の牌は動かせません。公開後は組み替えできますが、場の牌を残し、すべての列を合法にし、手札を一枚以上使います。",
        "手札をなくすと勝ちです。山が空のときの引きはパスです。全席がパスすると手札点の最も低い席が勝ちます。星は30点、数字は書かれた点です。同点は引き分けです。",
