        "木・花・ベンチは種類ごとの間隔を保ち、重ねて置けません。飾りは最大72個です。",
        "うさぎとカメラは現在の地形高をリアルタイムで追うため、作ったばかりの丘にもすぐ登れます。",
        "居心地は飾りの種類と地形を作った回数で上昇。競争スコアや制限時間はありません。",
