      ko: "단어 와플(Word Waffle)은 전 세계 퍼즐 마니아들에게 사랑받는 Waffle Game에서 영감을 받은 5×5 격자 글자 교환 퍼즐입니다. 가로 3줄과 세로 3줄이 교차하는 와플 보드 위에 섞여 있는 글자들을 15번의 기회 안에 교환하여 6개의 숨겨진 단어를 모두 밝혀내는 고품질 데일리 싱크탱크입니다.",
