          zh: "开荒期强烈建议优先点出‘大蒜结界’与‘旋转圣经’，二者可在主角周围构筑坚不可摧的近身击退安全圈；随后补足单体狙击利器‘魔法飞弹’与全局增伤的‘菠菜’，即可轻松在重重包围中杀出一条血路。",
