          ja: "グリーンランドやマダガスカルには空港がなく、唯一の交通路は港湾（海運）のみです。そのため『水（Water 1・2）』感染を進化させて貨物船経由での侵入率を高める必要があります。さらにグリーンランドは極寒地域のため『耐寒性（Cold Resistance 1・2）』が必須です。港が封鎖される前に船を送り込むことが勝敗を分けます。",
