          zh: "建议将体积最大的水果（水蜜桃、菠萝）固定在果箱左下或右下角落，并由大到小呈阶梯状向另一侧排列（香梨 → 苹果 → 柿子），这样能避免小樱桃卡在巨型水果下方浪费空间。",
