          zh: "没有对角支撑的四边形在承受垂直重力时极易变形坍塌，而三角形（如华伦式桁架）具有几何刚性，能将桥面受到的下压重力转化为沿杆件方向的张力与压力，均匀传导至两岸岩石锚点。",
