          ja: "雪線キャンプ(420m)からホークピーク山頂(550m)への最終アタックには黄金の羽が3つ(🪶×3)必要です。初期状態で2つ持っているため、道中の宝箱や祠を1つでも開ければ最大値が3以上になり、雪線キャンプで全回復してから登頂できます。",
